// Scans content/*.yml for unresolved markers and rewrites the auto-generated section of OPEN_ITEMS.md.
// Exported for the Astro integration (runs on every build); also runnable: `node scripts/open-items.mjs`.
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const ROOT = new URL('../', import.meta.url);
const MARKER = /\b(TBD|TBC|VERIFY|PLACEHOLDER|TO CONFIRM)\b|\[АНГЕЛ ПИШЕ|ДА СЕ ПОТВЪРДИ/;
// Phase 1 files gate the production build. The rest are listed for information only.
export const PHASE1 = ['site', 'landing', 'schools', 'companies', 'resume', 'support', 'offers', 'photos'];

export function scan() {
  const dir = new URL('content/', ROOT);
  const hits = [];
  for (const f of readdirSync(dir).filter((f) => f.endsWith('.yml')).sort()) {
    const name = f.replace(/\.yml$/, '');
    readFileSync(new URL(f, dir), 'utf8').split('\n').forEach((line, i) => {
      if (!MARKER.test(line)) return;
      const hash = line.search(/\s#\s/);
      const inComment = line.trimStart().startsWith('#') || (hash >= 0 && line.slice(hash).match(MARKER) && !line.slice(0, hash).match(MARKER));
      // English-only values are not shown until Phase 3, so they never block (Angel, 12 Nov 2026).
      const enOnly = /(^|[\s{,])en:\s*"[^"]*$|(^|[\s{,])en:\s*"[^"]*?(TBD|TBC|VERIFY|PLACEHOLDER|TO CONFIRM)/.test(line.replace(/\s#\s.*$/, ''));
      hits.push({ file: `content/${f}`, line: i + 1, text: line.trim().slice(0, 160), phase1: PHASE1.includes(name) && !enOnly, enOnly, inComment: !!inComment });
    });
  }
  return hits;
}

export function writeOpenItems(hits = scan()) {
  const path = new URL('OPEN_ITEMS.md', ROOT);
  const md = readFileSync(path, 'utf8');
  const row = (h) => `| \`${h.file}:${h.line}\` | ${h.inComment ? 'comment' : 'value'} | \`${h.text.replace(/\|/g, '\\|').replace(/`/g, "'")}\` |`;
  const block = (title, list) =>
    `### ${title}\n\n${list.length ? `| Where | Kind | Line |\n|---|---|---|\n${list.map(row).join('\n')}` : '_None._'}\n`;
  const auto = [
    '<!-- AUTO:START (generated by scripts/open-items.mjs on every build; do not edit by hand) -->',
    '## Unresolved markers in content files',
    '',
    block('Phase 1 files (block the production build)', hits.filter((h) => h.phase1)),
    block('English-only values and later-phase files (information only)', hits.filter((h) => !h.phase1)),
    '<!-- AUTO:END -->',
  ].join('\n');
  const out = md.replace(/<!-- AUTO:START[\s\S]*<!-- AUTO:END -->/, auto);
  if (out !== md) writeFileSync(path, out);
  return hits;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const hits = writeOpenItems();
  console.log(`${hits.filter((h) => h.phase1).length} Phase 1 markers, ${hits.filter((h) => !h.phase1).length} later-phase markers`);
}
